  "a_sentences": [
    {
      "a_text": "Streitig ist, ob die Vorinstanz Bundesrecht verletzte, indem sie dem Versicherten im Zusammenhang mit den Folgen des neuen Unfalls vom 8. September 2020 keine höhere Invalidenrente zusprach.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Gemäss Art. 17 Abs. 1 lit. a ATSG wird die Rente angepasst, wenn sich der Invaliditätsgrad um mindestens fünf Prozentpunkte ändert.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Bei einem Revisionsgrund ist der Rentenanspruch umfassend und ohne Bindung an frühere Beurteilungen neu zu prüfen.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Das Invalideneinkommen ist dem Versicherten als erzielbares Einkommen in einer leidensangepassten Tätigkeit anzurechnen.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Nach mehreren versicherten Unfällen ist der Invaliditätsgrad gesamthaft festzusetzen, wobei die Erheblichkeitsschwelle von fünf Prozentpunkten gilt.",
      "b_propositions": ["P5", "P6"]
    },
    {
      "a_text": "Der Invaliditätsgrad erhöhte sich lediglich um zwei Prozentpunkte und liegt damit unter der Schwelle von fünf Prozentpunkten.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Die Vorinstanz verletzte kein Bundesrecht, indem sie mangels einer wesentlichen Änderung die Invalidenrente bei einem Invaliditätsgrad von 32 % bestätigte.",
      "b_propositions": ["P8"]
    }
  ]
}
